-- Meetings people upload themselves: a recording, a transcript, or both, sent in parts so a
-- recording of gigabytes survives a dropped connection. See docs/meetings.md, Uploads.
--
-- An upload is staged here while its parts arrive. Finishing it makes its meeting (or a capture
-- of a meeting its person already has) and starts the meeting's run, whose fetch stores the
-- recording where the upload chose and the transcript as it was read.
CREATE TABLE meeting_uploads (
    -- UUIDv7, generated by the API.
    id UUID PRIMARY KEY,
    -- The meeting it adds a capture to. NULL for a new meeting, made when the upload finishes.
    meeting_id UUID REFERENCES meetings (id) ON DELETE CASCADE,
    -- A new meeting's title and when it started; a capture takes its meeting's.
    title TEXT CHECK (char_length(title) BETWEEN 1 AND 2048),
    started_at TIMESTAMPTZ,
    -- Where the recording is kept once the fetch stores it. NULL for a transcript alone.
    storage_location_id UUID REFERENCES storage_locations (id),
    -- How many bytes each part carries but the last, fixed when the upload starts, so a change to
    -- the constant never breaks an upload under way.
    part_bytes INTEGER NOT NULL CHECK (part_bytes > 0),
    -- The lines its transcript was read as, an array of `{ startMs, endMs, speaker, text }`, set
    -- when it finishes. NULL before, and for a recording alone.
    transcript JSONB CHECK (jsonb_typeof(transcript) = 'array'),
    -- The capture it became, once it finished. Unique, since one upload is one capture.
    capture_id UUID UNIQUE REFERENCES meeting_captures (id) ON DELETE CASCADE,
    finished_at TIMESTAMPTZ,
    -- Who uploads it: the meeting's owner.
    created_by UUID NOT NULL REFERENCES users (id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT meeting_uploads_new_meeting
        CHECK ((meeting_id IS NULL) = (title IS NOT NULL AND started_at IS NOT NULL)),
    CONSTRAINT meeting_uploads_finished
        CHECK ((finished_at IS NULL) = (capture_id IS NULL))
);

SELECT diesel_manage_updated_at('meeting_uploads');

-- A person's unfinished uploads, which the upload page resumes and the engine sweeps once stale.
CREATE INDEX meeting_uploads_unfinished ON meeting_uploads (created_by, updated_at)
    WHERE finished_at IS NULL;

-- The files of an upload: a recording, a transcript, or one of each. A child of its upload, so
-- it has no `created_by`.
CREATE TABLE meeting_upload_files (
    upload_id UUID NOT NULL REFERENCES meeting_uploads (id) ON DELETE CASCADE,
    -- `recording` or `transcript`.
    kind TEXT NOT NULL CHECK (kind IN ('recording', 'transcript')),
    -- Its name as the person's browser gave it, cleaned of paths and invisible characters.
    file_name TEXT NOT NULL CHECK (char_length(file_name) BETWEEN 1 AND 200),
    size_bytes BIGINT NOT NULL CHECK (size_bytes > 0),
    -- When the file was last changed, as the browser read it, so the page that picks the same
    -- file again resumes the upload rather than starting another.
    modified_at TIMESTAMPTZ,
    -- How many of its bytes have arrived, in whole parts from its start.
    received_bytes BIGINT NOT NULL DEFAULT 0
        CHECK (received_bytes >= 0 AND received_bytes <= size_bytes),
    PRIMARY KEY (upload_id, kind)
);
